export const KIND = {"id":24,"example":{"id":"E24","kind":24,"source":"aether","statement":["Write a function `water::state(int celsius)` that returns the state of water at that temperature.","The header also defines the result type, `enum class water::phase { solid, liquid, gas }`.","It returns `solid` at 0 or below, `liquid` below 100, and `gas` at 100 or above.","Limits: -1000 ≤ celsius ≤ 1000."],"examples":[],"tests":[],"solution":{"lines":["#pragma once","","namespace water {","","enum class phase { solid, liquid, gas };","","phase state(int celsius)","{","    if (celsius <= 0) {","        return phase::solid;","    } else if (celsius < 100) {","        return phase::liquid;","    } else {","        return phase::gas;","    }","}","","}  // namespace water"],"frame":[0,2,17],"labels":[{"at":4,"level":1,"text":"Name each possible value in an `enum class`."},{"at":4,"level":0,"text":"Write the values of an `enum class` between `{ }`, split by commas."},{"at":6,"level":1,"text":"Write a function that tests each case in order and gives back the result of the first that holds."},{"at":8,"level":2,"text":"Give back solid at 0 or below, liquid below 100, else gas."},{"at":9,"level":0,"text":"Name one value of the `enum class` as `phase::solid`."}],"blanks":[]}},"trace":{"id":"T24","lines":["#include <iostream>","#include <print>","","enum class band { low, high };","band band_of(int number)","{","    if (number < 10) {","        return band::low;","    }","    return band::high;","}","","int main()","{","    int number {0};","    std::cin >> number;","    std::println(\"{}\", band_of(number) == band::high);","}"],"columns":["number"],"inputs":["7\n","42\n"],"rows":[{"line":15,"values":["0"]},{"line":16,"values":["7"]},{"line":7,"values":["7"]},{"line":8,"values":["7"]},{"line":17,"values":["7"]}],"output":"true\n"},"traces":[],"problems":{"24.01":{"id":"24.01","kind":24,"source":"exercism","statement":["Write a function `triangle::kind(double a, double b, double c)` that returns the kind of the triangle with sides a, b and c.","The header also defines the result type, `enum class triangle::flavor { equilateral, isosceles, scalene }`.","It returns `equilateral` when all 3 sides are equal, `isosceles` when exactly 2 are equal, and `scalene` when no 2 are equal.","It throws `std::domain_error` when a side is 0 or less, or when one side is longer than the other 2 together.","Limits: none"],"examples":[{"input":"equilateral triangle -> all sides are equal","output":""}],"tests":[{"input":"equilateral triangle -> any side is unequal","output":""},{"input":"equilateral triangle -> no sides are equal","output":""},{"input":"equilateral triangle -> sides may be floats","output":""},{"input":"isosceles triangle -> last two sides are equal","output":""},{"input":"isosceles triangle -> first two sides are equal","output":""},{"input":"isosceles triangle -> first and last sides are equal","output":""},{"input":"isosceles triangle -> no sides are equal","output":""},{"input":"isosceles triangle -> first triangle inequality violation","output":""},{"input":"isosceles triangle -> second triangle inequality violation","output":""},{"input":"isosceles triangle -> third triangle inequality violation","output":""},{"input":"isosceles triangle -> sides may be floats","output":""},{"input":"scalene triangle -> no sides are equal","output":""},{"input":"scalene triangle -> may not violate triangle inequality","output":""},{"input":"scalene triangle -> sides may be floats","output":""},{"input":"all zero sides is not a triangle","output":""},{"input":"triangles_with_negative_sides_are_illegal","output":""},{"input":"double_and_integer_arguments","output":""}],"solution":{"lines":["#pragma once","","#include <stdexcept>","","namespace triangle {","","enum class flavor { equilateral, isosceles, scalene };","","flavor kind(double a, double b, double c)","{","    if (a <= 0 || b <= 0 || c <= 0 || a + b < c || a + c < b","        || b + c < a) {","        throw std::domain_error {\"not a triangle\"};","    }","    if (a == b && b == c) {","        return flavor::equilateral;","    } else if (a == b || b == c || a == c) {","        return flavor::isosceles;","    } else {","        return flavor::scalene;","    }","}","","}  // namespace triangle"],"frame":[0,2,4,23],"labels":[{"at":6,"level":1,"text":"Name each possible value in an `enum class`."},{"at":8,"level":1,"text":"Write a function that tests each case in order and gives back the result of the first that holds."},{"at":10,"level":2,"text":"Stop with an error when a side is 0 or less, or longer than the other 2 together."},{"at":14,"level":2,"text":"Give back equilateral when all 3 sides are equal, isosceles when 2 are, else scalene."}],"blanks":[{"line":6,"from":20,"to":31},{"line":8,"from":12,"to":40},{"line":11,"from":11,"to":20},{"line":16,"from":15,"to":41}]},"fn":{"slug":"triangle","commit":"8d139cb0","header":"triangle.h","name":"triangle_test.cpp","test":"#include \"triangle.h\"\n#ifdef EXERCISM_TEST_SUITE\n#include <catch2/catch.hpp>\n#else\n#include \"test/catch.hpp\"\n#endif\n#include <stdexcept>\n\n/*\nProblem spec commentary:\n\n    Pursuant to discussion in #202, we have decided NOT to test triangles\n    where all side lengths are positive but a + b = c. e.g:\n    (2, 4, 2, Isosceles), (1, 3, 4, Scalene).\n    It's true that the triangle inequality admits such triangles.These\n    triangles have zero area, however.\n    They're degenerate triangles with all three vertices collinear.\n    (In contrast, we will test (0, 0, 0, Illegal), as it is a point)\n    The tests assert properties of the triangle are true or false.\n    See: https://github.com/exercism/problem-specifications/issues/379 for\n    disscussion of this approach How you handle invalid triangles is up to you.\n    These tests suggest a triangle is returned, but all of its properties are\nfalse. But you could also have the creation of an invalid triangle return an\nerror or exception. Choose what is idiomatic for your language.\"\n\nThe CPP track has chosen to throw a domain error for invalid triangles.\n\nTests, that check if an equilateral is also scalene (etc.) do not work with\nthe chosen implementation, they are therefore not implemented for this track.\n\n*/\n\n// improves error messages with triangle flavor enum text instead of integers:\nCATCH_REGISTER_ENUM(triangle::flavor, triangle::flavor::equilateral,\n                    triangle::flavor::isosceles, triangle::flavor::scalene)\n\nTEST_CASE(\"equilateral triangle -> all sides are equal\",\n          \"[8b2c43ac-7257-43f9-b552-7631a91988af]\") {\n    REQUIRE(triangle::flavor::equilateral == triangle::kind(2, 2, 2));\n}\n\n#if defined(EXERCISM_RUN_ALL_TESTS)\n\nTEST_CASE(\"equilateral triangle -> any side is unequal\",\n          \"[33eb6f87-0498-4ccf-9573-7f8c3ce92b7b]\") {\n    REQUIRE_FALSE(triangle::flavor::equilateral == triangle::kind(2, 3, 2));\n}\n\nTEST_CASE(\"equilateral triangle -> no sides are equal\",\n          \"[c6585b7d-a8c0-4ad8-8a34-e21d36f7ad87]\") {\n    REQUIRE_FALSE(triangle::flavor::equilateral == triangle::kind(5, 4, 6));\n}\n\nTEST_CASE(\"equilateral triangle -> sides may be floats\",\n          \"[3022f537-b8e5-4cc1-8f12-fd775827a00c]\") {\n    REQUIRE(triangle::flavor::equilateral == triangle::kind(0.5, 0.5, 0.5));\n}\n\nTEST_CASE(\"isosceles triangle -> last two sides are equal\",\n          \"[cbc612dc-d75a-4c1c-87fc-e2d5edd70b71]\") {\n    REQUIRE(triangle::flavor::isosceles == triangle::kind(3, 4, 4));\n}\n\nTEST_CASE(\"isosceles triangle -> first two sides are equal\",\n          \"[e388ce93-f25e-4daf-b977-4b7ede992217]\") {\n    REQUIRE(triangle::flavor::isosceles == triangle::kind(4, 4, 3));\n}\n\nTEST_CASE(\"isosceles triangle -> first and last sides are equal\",\n          \"[d2080b79-4523-4c3f-9d42-2da6e81ab30f]\") {\n    REQUIRE(triangle::flavor::isosceles == triangle::kind(4, 3, 4));\n}\n\nTEST_CASE(\"isosceles triangle -> no sides are equal\",\n          \"[840ed5f8-366f-43c5-ac69-8f05e6f10bbb]\") {\n    REQUIRE_FALSE(triangle::flavor::isosceles == triangle::kind(2, 3, 4));\n}\n\nTEST_CASE(\"isosceles triangle -> first triangle inequality violation\",\n          \"[2eba0cfb-6c65-4c40-8146-30b608905eae]\") {\n    REQUIRE_THROWS_AS(triangle::kind(1, 1, 3), std::domain_error);\n}\n\nTEST_CASE(\"isosceles triangle -> second triangle inequality violation\",\n          \"[278469cb-ac6b-41f0-81d4-66d9b828f8ac]\") {\n    REQUIRE_THROWS_AS(triangle::kind(1, 3, 1), std::domain_error);\n}\n\nTEST_CASE(\"isosceles triangle -> third triangle inequality violation\",\n          \"[90efb0c7-72bb-4514-b320-3a3892e278ff]\") {\n    REQUIRE_THROWS_AS(triangle::kind(3, 1, 1), std::domain_error);\n}\n\nTEST_CASE(\"isosceles triangle -> sides may be floats\",\n          \"[adb4ee20-532f-43dc-8d31-e9271b7ef2bc]\") {\n    REQUIRE(triangle::flavor::isosceles == triangle::kind(0.5, 0.4, 0.5));\n}\n\nTEST_CASE(\"scalene triangle -> no sides are equal\",\n          \"[e8b5f09c-ec2e-47c1-abec-f35095733afb]\") {\n    REQUIRE(triangle::flavor::scalene == triangle::kind(5, 4, 6));\n}\n\nTEST_CASE(\"scalene triangle -> may not violate triangle inequality\",\n          \"[70ad5154-0033-48b7-af2c-b8d739cd9fdc]\") {\n    REQUIRE_THROWS_AS(triangle::kind(7, 3, 2), std::domain_error);\n}\n\nTEST_CASE(\"scalene triangle -> sides may be floats\",\n          \"[26d9d59d-f8f1-40d3-ad58-ae4d54123d7d]\") {\n    REQUIRE(triangle::flavor::scalene == triangle::kind(0.4, 0.6, 0.3));\n}\n\nTEST_CASE(\"all zero sides is not a triangle\",\n          \"[16e8ceb0-eadb-46d1-b892-c50327479251]\") {\n    REQUIRE_THROWS_AS(triangle::kind(0, 0, 0), std::domain_error);\n}\n\n// Tests that are not in the problem spec\n// kept for legacy and specific cpp functionality\n\nTEST_CASE(\"triangles_with_negative_sides_are_illegal\") {\n    REQUIRE_THROWS_AS(triangle::kind(3, 4, -5), std::domain_error);\n}\n\nTEST_CASE(\"double_and_integer_arguments\") {\n    REQUIRE(triangle::flavor::scalene == triangle::kind(5.5, 4, 2));\n}\n\n#endif\n","setup":[],"calls":[{"call":"triangle::kind(2, 2, 2)","expected":"triangle::flavor::equilateral"}]}},"24.02":{"id":"24.02","kind":24,"source":"aether","statement":["Write a function `compare::order(int a, int b)` that returns how a stands to b.","The header also defines the result type, `enum class compare::ordering { less, equal, greater }`.","It returns `less` when a is below b, `equal` when a equals b, and `greater` when a is above b.","Limits: -1000 ≤ a ≤ 1000; -1000 ≤ b ≤ 1000."],"examples":[{"input":"two_below_five","output":""}],"tests":[{"input":"five_above_two","output":""},{"input":"equal_numbers","output":""},{"input":"both_zero","output":""},{"input":"negative_below_zero","output":""},{"input":"smallest_and_largest","output":""},{"input":"largest_and_smallest","output":""},{"input":"one_apart","output":""}],"solution":{"lines":["#pragma once","","namespace compare {","","enum class ordering { less, equal, greater };","","ordering order(int a, int b)","{","    if (a < b) {","        return ordering::less;","    } else if (a == b) {","        return ordering::equal;","    } else {","        return ordering::greater;","    }","}","","}  // namespace compare"],"frame":[0,2,17],"labels":[{"at":4,"level":1,"text":"Name each possible value in an `enum class`."},{"at":6,"level":1,"text":"Write a function that tests each case in order and gives back the result of the first that holds."},{"at":8,"level":2,"text":"Give back less when a is below b, equal when they are equal, else greater."}],"blanks":[{"line":4,"from":22,"to":26},{"line":6,"from":15,"to":27},{"line":8,"from":8,"to":13}]},"fn":{"slug":"compare","commit":"","header":"compare.h","name":"compare_test.cpp","test":"#include \"compare.h\"\n#include \"test/catch.hpp\"\n\nTEST_CASE(\"two_below_five\") { REQUIRE(compare::order(2, 5) == compare::ordering::less); }\n#if defined(EXERCISM_RUN_ALL_TESTS)\nTEST_CASE(\"five_above_two\") { REQUIRE(compare::order(5, 2) == compare::ordering::greater); }\nTEST_CASE(\"equal_numbers\") { REQUIRE(compare::order(7, 7) == compare::ordering::equal); }\nTEST_CASE(\"both_zero\") { REQUIRE(compare::order(0, 0) == compare::ordering::equal); }\nTEST_CASE(\"negative_below_zero\") { REQUIRE(compare::order(-1, 0) == compare::ordering::less); }\nTEST_CASE(\"smallest_and_largest\") { REQUIRE(compare::order(-1000, 1000) == compare::ordering::less); }\nTEST_CASE(\"largest_and_smallest\") { REQUIRE(compare::order(1000, -1000) == compare::ordering::greater); }\nTEST_CASE(\"one_apart\") { REQUIRE(compare::order(-4, -5) == compare::ordering::greater); }\n#endif\n","setup":[],"calls":[{"call":"compare::order(2, 5)","expected":"compare::ordering::less"}]}}}}
